import { Link, useNavigate } from "react-router-dom";
import { useContext } from "react";
import { AuthContext } from "../context/AuthContext";

function Sidebar({ usage }) {
  const { user, setUser } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleLogout = () => {
    localStorage.removeItem("gigora_access_token");
    localStorage.removeItem("gigora_user");

    setUser(null);
    navigate("/login");
  };

  return (
    <div className="sidebar">
      <h2>Gigora</h2>

      {user && (
        <>
          <p className="user-name">
            Welcome, {user.name}
          </p>

          <p className="plan-text">
  {usage?.plan?.toUpperCase() || "FREE"} PLAN

  {usage?.plan === "pro" && (
    <span className="pro-badge">PRO</span>
  )}
</p>

          <p className="usage-text">
  {usage?.requests_used ?? 0}/{usage?.requests_limit ?? 5} Requests Used
</p>
        </>
      )}
      <Link to="/pricing">Pricing</Link>

      <ul>
        <li>
          <Link to="/profile-analyzer">
            Profile Analyzer
          </Link>
        </li>

        <li>
          <Link to="/gig-seo">
            Gig SEO
          </Link>
        </li>

        <li>
          <Link to="/proposal-generator">
            Proposal Generator
          </Link>
        </li>

        <li>
          <Link to="/history">
            History
          </Link>
        </li>

        <li>
          <Link to="/usage">
            Usage
          </Link>
        </li>
      </ul>

      {user && (
        <button
          className="sidebar-logout-btn"
          onClick={handleLogout}
        >
          Logout
        </button>
      )}
    </div>
  );
}

export default Sidebar;
